create policy "connect_attach_read" on storage.objects as permissive for select to authenticated using (((bucket_id = 'connect-attachments'::text) AND connect_attachment_read_ok(name)));
create policy "connect_attach_upload" on storage.objects as permissive for insert to authenticated with check (((bucket_id = 'connect-attachments'::text) AND connect_attachment_upload_ok(name)));
create policy "dira_active_account" on storage.objects as restrictive for all to authenticated using (( SELECT account_is_active() AS account_is_active)) with check (( SELECT account_is_active() AS account_is_active));
create policy "dira_scanned_files" on storage.objects as restrictive for select to authenticated using (file_is_downloadable(bucket_id, name, updated_at, owner));
create policy "storage_access_window" on storage.objects as restrictive for all to authenticated using (((bucket_id <> ALL (ARRAY['submissions'::text, 'learning-resources'::text])) OR ( SELECT participant_access_active() AS participant_access_active))) with check (((bucket_id <> ALL (ARRAY['submissions'::text, 'learning-resources'::text])) OR ( SELECT participant_access_active() AS participant_access_active)));
create policy "storage_course_delete" on storage.objects as permissive for delete to authenticated using (((bucket_id = 'course-materials'::text) AND (course_of_path(name) IS NOT NULL) AND can_edit_course(course_of_path(name))));
create policy "storage_course_read" on storage.objects as permissive for select to authenticated using (((bucket_id = 'course-materials'::text) AND (course_of_path(name) IS NOT NULL) AND can_view_course(course_of_path(name))));
create policy "storage_course_update" on storage.objects as permissive for update to authenticated using (((bucket_id = 'course-materials'::text) AND (course_of_path(name) IS NOT NULL) AND can_edit_course(course_of_path(name))));
create policy "storage_course_write" on storage.objects as permissive for insert to authenticated with check (((bucket_id = 'course-materials'::text) AND (course_of_path(name) IS NOT NULL) AND can_edit_course(course_of_path(name))));
create policy "storage_own_docs" on storage.objects as permissive for all to authenticated using (((bucket_id = ANY (ARRAY['application-documents'::text, 'submissions'::text, 'project-evidence'::text])) AND ((storage.foldername(name))[1] = (auth.uid())::text))) with check (((bucket_id = ANY (ARRAY['application-documents'::text, 'submissions'::text, 'project-evidence'::text])) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
create policy "storage_resources_read" on storage.objects as permissive for select to authenticated using (((bucket_id = 'learning-resources'::text) AND (is_staff() OR (app_role() = ANY (ARRAY['trainer'::role_code, 'me_officer'::role_code])) OR (EXISTS ( SELECT 1 FROM learning_resources r WHERE (r.storage_path = objects.name))))));
create policy "storage_resources_write" on storage.objects as permissive for all to authenticated using (((bucket_id = 'learning-resources'::text) AND (is_staff() OR (app_role() = 'trainer'::role_code)))) with check (((bucket_id = 'learning-resources'::text) AND (is_staff() OR (app_role() = 'trainer'::role_code))));
create policy "storage_staff_read" on storage.objects as permissive for select to authenticated using ((((bucket_id = 'application-documents'::text) AND is_staff()) OR ((bucket_id = ANY (ARRAY['submissions'::text, 'project-evidence'::text])) AND (is_staff() OR (app_role() = 'me_officer'::role_code) OR ((app_role() = 'trainer'::role_code) AND (EXISTS ( SELECT 1 FROM (participants p JOIN cohort_enrolments e ON ((e.participant_id = p.id))) WHERE (((p.profile_id)::text = (storage.foldername(objects.name))[1]) AND (e.cohort_id IN ( SELECT my_trainer_cohorts() AS my_trainer_cohorts))))))))));
